// OrderFilters.tsx
import { Button, Select } from '@cloudscape-design/components';

export function OrderFilters({ onApply, statuses }: { onApply: (f: any) => void; statuses: string[] }) {
  // status and min are each kept in their own local state hook (default 'all' and '')
  const handle = () => {
    if (min && isNaN(Number(min))) { alert('Minimum must be a number'); return; }
    onApply({ status, min: min ? Number(min) : undefined });
  };
  return (
    <div style={{ display: 'flex', gap: 12, padding: 8 }}>
      <Select
        selectedOption={{ value: status, label: status }}
        options={statuses.map((s) => ({ value: s, label: s }))}
        onChange={({ detail }) => setStatus(detail.selectedOption.value!)}
      />
      <input value={min} placeholder="Min total" onChange={(e) => setMin(e.target.value)} />
      <button onClick={handle}>Apply</button>
    </div>
  );
}
